"use client";

import { useId, useRef, useState, useSyncExternalStore, type FocusEvent, type ReactNode, type Ref } from "react";
import { Select as BaseSelect } from "@base-ui/react/select";
import { Icon } from "../icons/icons";
import { useHighlight } from "../listbox/use-highlight";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./select.module.css";

export type SelectOption = {
  value: string;
  /** Plain text; the native picker shows it on touch screens. */
  label: string;
  /** Second line in the list; not shown by the native picker. */
  description?: string;
  /** A 16px mark before the label, in the list and on the trigger (a brand
   * mark, a flag). Give every option one or none, so the trigger doesn't
   * change shape. Not shown by the native picker. */
  icon?: ReactNode;
  disabled?: boolean;
};

export type SelectGroup = { label: string; options: SelectOption[] };

type Item = SelectOption | SelectGroup;

const isGroup = (item: Item): item is SelectGroup => "options" in item;

type SelectProps = {
  options: Item[];
  /** Visible label above the field. Without one, pass `aria-label`. */
  label?: string;
  "aria-label"?: string;
  /** Shown under the field when there's no error. */
  hint?: string;
  /** Return an error message, or null when valid. Runs on blur. */
  validate?: (value: string) => string | null;
  /** External error; wins over `validate`. */
  error?: string | null;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  /** `md` is a form field; `sm` is a compact pill. */
  size?: "sm" | "md";
  name?: string;
  required?: boolean;
  disabled?: boolean;
  id?: string;
  className?: string;
  ref?: Ref<HTMLButtonElement>;
};

const COARSE = "(pointer: coarse)";

function subscribeCoarse(onChange: () => void) {
  const query = matchMedia(COARSE);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
}

function assignRef<T>(ref: Ref<T> | undefined, value: T) {
  if (typeof ref === "function") ref(value);
  else if (ref) ref.current = value;
}

/** A select-only combobox on Base UI's Select; on touch screens the native picker takes over. */
export function Select({
  options,
  label,
  "aria-label": ariaLabel,
  hint,
  validate,
  error: externalError,
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  placeholder = "Choose…",
  size = "md",
  name,
  required,
  disabled = false,
  id,
  className,
  ref,
}: SelectProps) {
  const baseId = useId();
  const triggerId = id ?? `${baseId}-trigger`;
  const nativeId = `${baseId}-native`;
  const messageId = `${baseId}-message`;

  const flat = options.flatMap((item) => (isGroup(item) ? item.options : [item]));
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue);
  const value = controlledValue ?? uncontrolledValue;
  const selected = flat.find((o) => o.value === value) ?? null;

  const native = useSyncExternalStore(subscribeCoarse, () => matchMedia(COARSE).matches, () => false);

  const [localError, setLocalError] = useState<string | null>(null);
  const error = externalError ?? localError;
  const message = error ?? hint;
  const hasMessage = Boolean(hint || validate || externalError !== undefined);

  const [open, setOpen] = useState(false);
  // Floating content portals into the nearest themed subtree, so it keeps its tokens.
  const [container, setContainer] = useState<HTMLElement | null>(null);
  const popupRef = useRef<HTMLDivElement>(null);
  const { listRef, barRef } = useHighlight({ centerSelected: true });

  function commit(next: string) {
    if (controlledValue === undefined) setUncontrolledValue(next);
    if (next !== value) onValueChange?.(next);
    if (localError) setLocalError(validate?.(next) ?? null);
  }

  function runValidate(current: string) {
    setLocalError(validate?.(current) ?? null);
  }

  function onBlur(event: FocusEvent<HTMLElement>) {
    // Moving into the list isn't leaving the field.
    const next = event.relatedTarget as Node | null;
    if (next && popupRef.current?.contains(next)) return;
    runValidate(event.currentTarget instanceof HTMLSelectElement ? event.currentTarget.value : value);
  }

  function setRefs(node: HTMLButtonElement | null) {
    setContainer(node?.closest<HTMLElement>("[data-theme]") ?? null);
    assignRef(ref, node);
  }

  const renderOption = (option: SelectOption) => (
    <BaseSelect.Item
      key={option.value}
      value={option.value}
      label={option.label}
      disabled={option.disabled}
      className={styles.option}
    >
      {option.icon && (
        <span className={styles.icon} aria-hidden="true">
          {option.icon}
        </span>
      )}
      <span className={styles.text}>
        <BaseSelect.ItemText className={styles.optionLabel}>{option.label}</BaseSelect.ItemText>
        {option.description && <span className={styles.description}>{option.description}</span>}
      </span>
      <span className={styles.check} aria-hidden="true">
        <Icon name="check" />
      </span>
    </BaseSelect.Item>
  );

  return (
    <div
      className={className ? `${styles.field} ${className}` : styles.field}
      data-size={size}
      data-native={native || undefined}
    >
      <BaseSelect.Root<string>
        value={selected ? value : null}
        onValueChange={(next) => commit(next ?? "")}
        open={open && !native}
        onOpenChange={(next, details) => {
          setOpen(next);
          // Leaving the field by pressing elsewhere or tabbing away validates, like blur.
          if (!next && (details.reason === "outside-press" || details.reason === "focus-out")) runValidate(value);
        }}
        modal={false}
        name={native ? undefined : name}
        required={native ? undefined : required}
        disabled={disabled}
      >
        {label &&
          (native ? (
            <label htmlFor={nativeId} className={styles.label}>
              {label}
            </label>
          ) : (
            <BaseSelect.Label className={styles.label}>{label}</BaseSelect.Label>
          ))}
        <div className={styles.control}>
          <BaseSelect.Trigger
            ref={setRefs}
            id={triggerId}
            className={styles.trigger}
            inert={native || undefined}
            aria-label={label ? undefined : ariaLabel}
            aria-invalid={error ? true : undefined}
            aria-describedby={hasMessage && message ? messageId : undefined}
            onBlur={native ? undefined : onBlur}
          >
            {selected?.icon && (
              <span className={styles.icon} aria-hidden="true">
                {selected.icon}
              </span>
            )}
            <TextMorph className={styles.value}>{selected?.label ?? placeholder}</TextMorph>
            <Icon name={open ? "chevron-up" : "chevron-down"} className={styles.chevron} />
          </BaseSelect.Trigger>
          {/* On touch screens the system picker is the control, over the same trigger. */}
          {native && (
            <select
              id={nativeId}
              className={styles.native}
              name={name}
              value={value}
              disabled={disabled}
              required={required}
              aria-label={label ? undefined : ariaLabel}
              aria-invalid={error ? true : undefined}
              aria-describedby={hasMessage && message ? messageId : undefined}
              onChange={(event) => commit(event.currentTarget.value)}
              onBlur={onBlur}
            >
              {!selected && (
                <option value="" disabled hidden>
                  {placeholder}
                </option>
              )}
              {options.map((item) =>
                isGroup(item) ? (
                  <optgroup key={item.label} label={item.label}>
                    {item.options.map((o) => (
                      <option key={o.value} value={o.value} disabled={o.disabled}>
                        {o.label}
                      </option>
                    ))}
                  </optgroup>
                ) : (
                  <option key={item.value} value={item.value} disabled={item.disabled}>
                    {item.label}
                  </option>
                ),
              )}
            </select>
          )}
        </div>
        {hasMessage && (
          <p id={messageId} className={styles.message} aria-live="polite">
            {error ? (
              <span key={error} className={styles.error}>
                <svg viewBox="0 0 16 16" aria-hidden="true">
                  <circle cx="8" cy="8" r="6.25" fill="none" stroke="currentColor" />
                  <path d="M8 4.75v3.75" stroke="currentColor" strokeLinecap="round" />
                  <circle cx="8" cy="11" r="0.9" fill="currentColor" />
                </svg>
                {error}
              </span>
            ) : (
              hint && <span className={styles.hint}>{hint}</span>
            )}
          </p>
        )}
        {!native && (
          <BaseSelect.Portal container={container ?? undefined}>
            <BaseSelect.Positioner
              className={styles.popup}
              data-size={size}
              alignItemWithTrigger={false}
              side="bottom"
              align="start"
              sideOffset={8}
              collisionPadding={8}
            >
              <BaseSelect.Popup ref={popupRef} className={styles.panel}>
                <BaseSelect.List ref={listRef} className={styles.list}>
                  <span ref={barRef} className={styles.highlight} aria-hidden="true" />
                  {options.map((item) =>
                    isGroup(item) ? (
                      <BaseSelect.Group key={item.label} className={styles.group}>
                        <BaseSelect.GroupLabel className={styles.groupLabel}>{item.label}</BaseSelect.GroupLabel>
                        {item.options.map(renderOption)}
                      </BaseSelect.Group>
                    ) : (
                      renderOption(item)
                    ),
                  )}
                </BaseSelect.List>
              </BaseSelect.Popup>
            </BaseSelect.Positioner>
          </BaseSelect.Portal>
        )}
      </BaseSelect.Root>
    </div>
  );
}

@layer theme, base, components, utilities;

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .root {
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    /* The card changes size only when the result replaces the form: then it
       glides to the new size, with no overshoot. Inside the form, the parts
       that open (the error) pace themselves and the card follows them frame
       by frame, so nothing chases. */
    --animated-size-grow: 0s;
    --animated-size-shrink: 0s;
    --animated-size-ease: var(--ui-ease-glide);
    display: grid;
    gap: var(--ui-space-5);
    width: 100%;
    max-width: 360px;
    padding: var(--ui-space-6) var(--ui-space-5) var(--ui-space-5);
    border-radius: var(--ui-radius-lg);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-resting);
    color: var(--ui-foreground);
    font-family: var(--ui-font-sans);
  }

  .root:is([data-status="connected"], [data-status="denied"]) {
    --animated-size-grow: var(--ui-dur-glide);
    --animated-size-shrink: var(--ui-dur-glide);
  }

  /* Two app tiles joined by a dotted line. Nothing sits on the line while
     the person decides. While the grant is issued, a soft band of light
     passes along the dots toward the server, in step with the button's own
     sweep. Connected: the line draws in solid and a check appears on it.
     Failed: the dots step back and an x appears. Cancelled: the dots step
     back. One quiet change per state, no bounce. */
  .marks {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .mark {
    display: grid;
    place-items: center;
    flex-shrink: 0;
    width: var(--ui-control-lg);
    height: var(--ui-control-lg);
    overflow: hidden;
    border-radius: var(--ui-radius-md);
    background: var(--ui-surface);
    box-shadow:
      var(--ui-edge),
      var(--ui-shadow-raised);
    color: var(--ui-foreground);
  }

  .mark > :is(img, svg) {
    width: 28px;
    height: 28px;
  }

  /* No logo: the first letter on a tint picked from the name. The tint is
     the accent turned to another hue, at the accent's own lightness and
     chroma, so every monogram has the same weight and contrast as the
     accent does, in light and dark. */
  .monogram {
    --authorize-tint: var(--ui-accent);
    --authorize-tint: oklch(from var(--ui-accent) l c var(--authorize-hue));
    --authorize-letter: var(--ui-accent-text);
    --authorize-letter: oklch(from var(--ui-accent-text) l c var(--authorize-hue));
    background: color-mix(in oklch, var(--authorize-tint) 12%, var(--ui-surface));
    box-shadow:
      inset 0 0 0 var(--ui-hairline) color-mix(in oklch, var(--authorize-tint) var(--ui-border-tint), transparent),
      var(--ui-shadow-raised);
    color: var(--authorize-letter);
    font-size: var(--ui-text-2xl);
    font-weight: var(--ui-weight-semibold);
    line-height: 1;
    letter-spacing: var(--ui-tracking-title);
  }

  .link {
    --authorize-dot: 6px;
    position: relative;
    display: grid;
    place-items: center;
    /* Twelve dots, one every 6px. */
    width: calc(var(--authorize-dot) * 12);
    height: var(--ui-icon-md);
    margin-inline: var(--ui-space-3);
  }

  .dots,
  .dots::after,
  .solid {
    position: absolute;
    inset-inline: 0;
    top: 50%;
  }

  .dots {
    height: 4px;
    margin-top: -2px;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .dots::before,
  .dots::after {
    content: "";
    inset: 0;
    background: radial-gradient(circle 1.25px, currentColor 70%, transparent) 0 0 / var(--authorize-dot) 100% repeat-x;
  }

  .dots::before {
    position: absolute;
    color: var(--ui-subtle);
    opacity: 0.6;
  }

  /* The band: the same dots in the muted tone, seen through a soft window
     that travels toward the server. Off until submitting. */
  .dots::after {
    margin-top: 0;
    color: var(--ui-muted);
    opacity: 0;
    mask-image: linear-gradient(90deg, transparent 35%, black 50%, transparent 65%);
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    mask-position: 100% 0;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .root[data-status="submitting"] .dots::after {
    opacity: 1;
    transition-duration: var(--ui-dur-base);
    animation: authorize-sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes authorize-sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  /* The solid line, drawn from the asking app toward the server. */
  .solid {
    height: 1.5px;
    margin-top: -0.75px;
    border-radius: var(--ui-radius-full);
    background: var(--ui-ink);
    clip-path: inset(0 100% 0 0);
    transition: clip-path var(--ui-dur-instant) var(--ui-ease-exit);
  }

  /* The result, on the middle of the line: a small disc that fades in,
     never grows or swaps glyphs. */
  .result {
    position: relative;
    display: grid;
    place-items: center;
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    border-radius: var(--ui-radius-full);
    grid-area: 1 / 1;
    opacity: 0;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .result > svg {
    width: var(--ui-icon-xs);
    height: var(--ui-icon-xs);
    /* The medium line, drawn at 12px. */
    --ui-icon-stroke: calc(var(--ui-icon-stroke-medium) * 16 / 12);
  }

  /* A ring of the card's surface parts the line around the disc. */
  .result {
    box-shadow: 0 0 0 var(--ui-knockout) var(--ui-surface);
  }

  .result[data-result="connected"] {
    background: var(--ui-ink);
    color: var(--ui-on-ink);
  }

  .result[data-result="error"] {
    background: color-mix(in oklch, var(--ui-danger) 10%, var(--ui-surface));
    box-shadow:
      0 0 0 var(--ui-hairline) var(--ui-border-danger),
      0 0 0 var(--ui-knockout) var(--ui-surface);
    color: var(--ui-danger);
  }

  /* Connected: the dots give way to the solid line as it draws, and the
     check fades in once the line has reached it. */
  .root[data-status="connected"] .dots {
    opacity: 0;
    transition-duration: var(--ui-dur-glide);
  }

  .root[data-status="connected"] .solid {
    clip-path: inset(0);
    transition: clip-path var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .root[data-status="connected"] .result[data-result="connected"] {
    opacity: 1;
    transition: opacity var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-glide) / 4);
  }

  /* Failed: the line steps back and the x fades in. */
  .root[data-status="error"] .dots {
    opacity: 0.5;
  }

  .root[data-status="error"] .result[data-result="error"] {
    opacity: 1;
    transition: opacity var(--ui-dur-fast) var(--ui-ease-enter);
  }

  /* Cancelled: nothing is joined; the line steps back. */
  .root[data-status="denied"] .dots {
    opacity: 0.4;
  }

  .body {
    display: grid;
    gap: var(--ui-space-5);
  }

  /* The result fades in while the card glides to its size: no rise, no
     delay, so the card is never seen empty. */
  .body[data-enter] {
    animation: authorize-in var(--ui-dur-base) var(--ui-ease-enter) backwards;
  }

  @keyframes authorize-in {
    from {
      opacity: 0;
    }
  }

  /* Centered: who wants what, and as whom. The list below stays aligned to
     its boxes, because centered checkboxes don't line up. */
  .head {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    gap: var(--ui-space-2);
    text-align: center;
  }

  .title {
    margin: 0;
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-semibold);
    line-height: var(--ui-leading-md);
    text-wrap: balance;
  }

  .title:focus {
    outline: none;
  }

  .sub {
    min-width: 0;
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
    overflow-wrap: anywhere;
  }

  /* The account select, the compact pill, under the heading. The row is the
     card's full width so a long email is cut at its edge instead of running
     past it; the pill centers in it. Its options read from the start. */
  .accountRow {
    width: 100%;
  }

  .accountRow .account {
    justify-items: center;
    text-align: start;
  }

  /* Set off by a hairline above and below, so the list reads as the one
     thing to check. */
  .scopes {
    display: grid;
    padding-block: var(--ui-space-4);
    box-shadow:
      inset 0 var(--ui-hairline) 0 var(--ui-border),
      inset 0 calc(var(--ui-hairline) * -1) 0 var(--ui-border);
  }

  .scopes ul {
    display: grid;
    gap: var(--ui-space-3);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* Required rows line their text up with the checkbox labels around them. */
  .scope {
    display: grid;
    grid-template-columns: 16px minmax(0, 1fr);
    column-gap: var(--ui-space-2);
    align-items: start;
  }

  /* A required permission: the same box as the checkboxes beside it, filled
     in a neutral tone and without hover, so it reads as on and fixed. */
  .locked {
    display: grid;
    place-items: center;
    width: 16px;
    height: 16px;
    margin-top: 3px;
    border-radius: calc(var(--ui-radius-sm) / 2);
    background: var(--ui-fill-strong);
    color: var(--ui-muted);
  }

  .locked > svg {
    width: var(--ui-icon-xs);
    height: var(--ui-icon-xs);
    /* The regular line, drawn at 12px. */
    --ui-icon-stroke: calc(var(--ui-icon-stroke-regular) * 16 / 12);
  }

  .text {
    display: grid;
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .description {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-regular);
    line-height: var(--ui-leading-sm);
  }

  /* Centered with the rest; the icon sits in the line like a word. */
  .warning,
  .error {
    margin: 0;
    text-align: center;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .warning > svg,
  .error > svg {
    display: inline-block;
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    margin-inline-end: var(--ui-space-1);
    vertical-align: -3px;
  }

  .warning {
    color: var(--ui-warning-text);
  }

  .warning > svg {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    color: var(--ui-warning);
  }

  /* Its room opens and closes on the glide, and the return line under it
     moves with it. */
  .errorSlot {
    --animated-size-grow: var(--ui-dur-glide);
    --animated-size-shrink: var(--ui-dur-base);
  }

  .error {
    padding-top: var(--ui-gap-stack);
    color: var(--ui-danger-text);
    animation: authorize-in var(--ui-dur-base) var(--ui-ease-enter);
  }

  .error > svg {
    color: var(--ui-danger);
  }

  /* Allow, then Cancel under it, then where the browser goes next. */
  .foot {
    display: grid;
  }

  .buttons {
    display: grid;
    gap: var(--ui-gap-tight);
  }

  .host {
    min-width: 0;
    margin: var(--ui-gap-stack) 0 0;
    text-align: center;
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    overflow-wrap: anywhere;
  }

  .host code {
    color: var(--ui-muted);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-code);
  }

  @media (prefers-reduced-motion: reduce) {
    .body[data-enter],
    .error {
      animation: none;
    }
    /* No band: the dots take the muted tone in place while submitting, and
       the solid line fades in whole instead of drawing. */
    .root[data-status="submitting"] .dots::after {
      animation: none;
      mask-image: none;
    }
    .solid,
    .root[data-status="connected"] .solid {
      clip-path: none;
      opacity: 0;
      transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
    }
    .root[data-status="connected"] .solid {
      opacity: 1;
    }
    .root[data-status="connected"] .result[data-result="connected"] {
      transition-delay: 0s;
    }
  }
}

"use client";

import { useId, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { AnimatedSize } from "../animated-size/animated-size";
import { Button } from "../button/button";
import { Checkbox } from "../checkbox/checkbox";
import { Icon } from "../icons/icons";
import { useDelayedBusy } from "../button/use-delayed-busy";
import { Select } from "../select/select";
import styles from "./authorize.module.css";

export type AuthorizeStatus = "review" | "submitting" | "connected" | "denied" | "error";

export type AuthorizeScope = {
  id: string;
  /** What it lets the client do, starting with the verb: "See your bookings", "Issue refunds". */
  title: string;
  /** One short line, only when the title isn't enough. */
  description?: string;
  /** Whether it can change anything. Unticking every `write` scope makes the button "Allow read-only". */
  access: "read" | "write";
  /** Required scopes can't be unticked; optional ones show a checkbox. */
  required?: boolean;
  /** Optional scopes start ticked unless this is false. */
  defaultGranted?: boolean;
};

type Party = {
  name: string;
  /** A logo, drawn at 28px on a 48px tile. Without one, the first letter stands in, on a tint picked from the name. */
  mark?: ReactNode;
};

type AuthorizeProps = {
  /** The agent or app asking. `returnTo` is the redirect URI's host and port. */
  client: Party & { returnTo: string; verified?: boolean };
  /** Your MCP server or app. */
  server: Party;
  /** Who is signed in. Without it, the account line is left out. */
  account?: { email: string };
  /** Other accounts signed in on this browser, offered in the account select. */
  otherAccounts?: string[];
  /** Called with the email picked, or with nothing for "Use another account". Without it, the email is plain text. */
  onSwitchAccount?: (email?: string) => void;
  scopes: AuthorizeScope[];
  /** Controlled. `submitting` while your server issues the grant. */
  status?: AuthorizeStatus;
  /** Shown with `error`. Say what failed. */
  error?: string;
  /** Called with the ids of every scope the person left ticked. */
  onAllow: (granted: string[]) => void;
  onDeny: () => void;
  headingLevel?: 1 | 2 | 3;
  className?: string;
};

/** The select's "Use another account" option. */
const OTHER = "__other__";

/** Hues a monogram can land on, spread so two names rarely share one. */
const HUES = [262, 290, 330, 18, 52, 150, 190, 228];

/** The same name always gets the same hue, so an app keeps its color between visits. */
function hueOf(name: string) {
  let h = 0;
  for (const c of name.trim().toLowerCase()) h = (h * 31 + c.codePointAt(0)!) >>> 0;
  return HUES[h % HUES.length];
}

function Mark({ party }: { party: Party }) {
  if (party.mark) return <span className={styles.mark}>{party.mark}</span>;
  return (
    <span className={`${styles.mark} ${styles.monogram}`} style={{ "--authorize-hue": hueOf(party.name) } as CSSProperties}>
      {[...party.name.trim()][0]?.toLocaleUpperCase()}
    </span>
  );
}

/** An OAuth consent screen for an agent connecting to an MCP server. */
export function Authorize({
  client,
  server,
  account,
  otherAccounts = [],
  onSwitchAccount,
  scopes,
  status = "review",
  error,
  onAllow,
  onDeny,
  headingLevel = 1,
  className,
}: AuthorizeProps) {
  const H = `h${headingLevel}` as "h1";
  const titleId = useId();
  const resultRef = useRef<HTMLHeadingElement>(null);
  const [granted, setGranted] = useState(
    () => new Set(scopes.filter((s) => s.required || s.defaultGranted !== false).map((s) => s.id)),
  );

  const settled = status === "connected" || status === "denied";
  const busy = status === "submitting";
  // The controls dim when the button shows it's busy, not at the click, so
  // a quick grant never flashes the list.
  const busyShown = useDelayedBusy(busy);
  const writes = scopes.filter((s) => s.access === "write");
  const readOnly = writes.length > 0 && writes.every((s) => !granted.has(s.id));

  // A retry keeps "Try again" until the busy label takes over, instead of
  // flicking back to "Allow" for the first 300ms.
  const [prevStatus, setPrevStatus] = useState(status);
  const [retrying, setRetrying] = useState(false);
  if (status !== prevStatus) {
    setPrevStatus(status);
    setRetrying(status === "submitting" && (prevStatus === "error" || (prevStatus === "submitting" && retrying)));
  }
  const label = status === "error" || (busy && retrying) ? "Try again" : readOnly ? "Allow read-only" : "Allow";

  // The result replaces the buttons, so focus follows it.
  const wasSettled = useRef(settled);
  useLayoutEffect(() => {
    if (settled && !wasSettled.current) resultRef.current?.focus();
    wasSettled.current = settled;
  }, [settled]);

  function toggle(id: string, on: boolean) {
    setGranted((all) => {
      const next = new Set(all);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });
  }

  return (
    <section
      className={className ? `${styles.root} ${className}` : styles.root}
      data-status={status}
      aria-labelledby={titleId}
      aria-busy={busy || undefined}
    >
      <div className={styles.marks} aria-hidden="true">
        <Mark party={client} />
        {/* A dotted line that turns solid once they're joined. Only a result
            gets a mark: a check when connected, an x when it failed. */}
        <span className={styles.link}>
          <span className={styles.dots} />
          <span className={styles.solid} />
          <span className={styles.result} data-result="connected">
            <Icon name="check" />
          </span>
          <span className={styles.result} data-result="error">
            <Icon name="close" />
          </span>
        </span>
        <Mark party={server} />
      </div>

      <AnimatedSize>
        {settled ? (
          <div key="result" className={styles.body} data-enter>
            <div className={styles.head}>
              <H id={titleId} ref={resultRef} tabIndex={-1} className={styles.title}>
                {status === "connected" ? `Connected to ${server.name}` : "Not connected"}
              </H>
              <p className={styles.sub}>
                {status === "connected"
                  ? `You can close this tab and go back to ${client.name}.`
                  : `Nothing from ${server.name} was shared with ${client.name}.`}
              </p>
            </div>
          </div>
        ) : (
          <div key="review" className={styles.body}>
            <div className={styles.head}>
              <H id={titleId} className={styles.title}>
                {client.name} wants to access {server.name}
              </H>
              {account &&
                (onSwitchAccount ? (
                  <div className={`${styles.sub} ${styles.accountRow}`}>
                    {/* Which account it acts as is a choice of value, so it's a select. */}
                    <Select
                      size="sm"
                      aria-label="Account"
                      className={styles.account}
                      disabled={busyShown}
                      value={account.email}
                      onValueChange={(v) => onSwitchAccount(v === OTHER ? undefined : v)}
                      options={[
                        ...[account.email, ...otherAccounts.filter((e) => e !== account.email)].map((e) => ({ value: e, label: e })),
                        { value: OTHER, label: "Use another account" },
                      ]}
                    />
                  </div>
                ) : (
                  <p className={styles.sub}>{account.email}</p>
                ))}
            </div>

            <div className={styles.scopes} inert={busy || undefined}>
              <ul aria-label="It will be able to">
                {scopes.map((s) =>
                  s.required ? (
                    <li key={s.id} className={styles.scope}>
                      <span className={styles.locked} aria-hidden="true">
                        <Icon name="check" />
                      </span>
                      <span className={styles.text}>
                        <span>
                          {s.title}
                          <span className={styles.srOnly}> (always included)</span>
                        </span>
                        {s.description && <span className={styles.description}>{s.description}</span>}
                      </span>
                    </li>
                  ) : (
                    <li key={s.id}>
                      <Checkbox
                        label={s.title}
                        description={s.description}
                        checked={granted.has(s.id)}
                        disabled={busyShown}
                        onCheckedChange={(on) => toggle(s.id, on)}
                      />
                    </li>
                  ),
                )}
              </ul>
            </div>

            {!client.verified && (
              <p className={styles.warning}>
                <Icon name="warning" />
                <span>
                  {server.name} hasn’t verified {client.name}. Only allow it if you started this yourself.
                </span>
              </p>
            )}

            <div className={styles.foot}>
              <div className={styles.buttons}>
                <Button busy={busy} busyLabel="Connecting…" onClick={() => onAllow(scopes.filter((s) => granted.has(s.id)).map((s) => s.id))}>
                  {label}
                </Button>
                <Button variant="ghost" onClick={() => !busy && onDeny()} disabled={busyShown}>
                  Cancel
                </Button>
              </div>
              {/* Under Cancel, not above Allow: the button just pressed never
                  moves. Its room opens smoothly, so the line under it glides. */}
              <AnimatedSize className={styles.errorSlot}>
                {status === "error" && (
                  <p className={styles.error} role="alert">
                    <Icon name="alert" />
                    <span>{error ?? `${server.name} couldn’t finish connecting. Nothing was shared.`}</span>
                  </p>
                )}
              </AnimatedSize>
              <p className={styles.host}>
                You’ll return to <code>{client.returnTo}</code>
              </p>
            </div>
          </div>
        )}
      </AnimatedSize>

      <span role="status" className={styles.srOnly}>
        {busy ? `Connecting ${client.name} to ${server.name}` : ""}
      </span>
    </section>
  );
}
